import React, { useState } from "react";

function FormHandeling() {
  const [formvalue, setFormhandel] = useState({
    id: "",
    name: "",
    email: "",
    password: "",
  });

  const [data, setData] = useState([]);

  const changeHandel = (e) => {
    setFormhandel({
      ...formvalue,
      id: new Date().getTime().toString(),
      [e.target.name]: e.target.value,
    });
  };

  const submitHandel = (e) => {
    e.preventDefault();
    setData([...data, formvalue]);
    setFormhandel({ id: "", name: "", email: "", password: "" });
  };

  const deleteHandel = (id) => {
    const filterdata = data.filter((value) => value.id !== id);
    setData(filterdata);
  };

  return (
<div className="bg-light min-vh-100 py-5">
<div className="container">
<div className="card shadow border-0 mb-5">
<div className="card-header bg-primary text-white text-center">
<h4>User Register</h4>
</div>

<div className="card-body">
<form onSubmit={submitHandel}>
<div className="row">
<div className="col-md-4 mb-3">

<label className="form-label fw-bold">Name</label>
<input type="text" name="name" value={formvalue.name} onChange={changeHandel}
className="form-control" placeholder="Enter Name" required />
</div><br/>

<div className="col-md-4 mb-3">
<label className="form-label fw-bold">Email</label>
<input type="email" name="email" value={formvalue.email} onChange={changeHandel}
className="form-control" placeholder="Enter Email" required/>
</div><br/>

<div className="col-md-4 mb-3">
<label className="form-label fw-bold">Password</label>
<input type="password" name="password" value={formvalue.password} onChange={changeHandel}
className="form-control" placeholder="Enter Password" required /><br/><br/>
</div> 
              </div>

              <button className="btn btn-success w-100 mt-3"> Delete</button>
            </form>
          </div>
        </div>

        <div className="card shadow border-0">
          <div className="card-header bg-dark text-white text-center">
            <h4>User Manage</h4>
          </div>

          <div className="card-body">
            <div className="table-responsive">
              <table className="table table-striped table-hover text-center align-middle">
                <thead className="table-dark">
                  <tr>
                    <th>ID</th>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Password</th>
                    <th>Action</th>
                  </tr>
                </thead>

                <tbody>
                  {data.length > 0 ? (
                    data.map((value) => (
                      <tr key={value.id}>
                        <td className="text-muted small">{value.id}</td>
                        <td className="fw-bold">{value.name}</td>
                        <td>{value.email}</td>
                        <td>
                          <span className="badge bg-secondary">
                            {value.password}
                          </span>
                        </td>
                        <td>
<button onClick={() => deleteHandel(value.id)} className="btn btn-danger btn-sm">Delete
</button>
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan="5" className="text-muted">
                        No Data Found !!
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default FormHandeling;
